import type { Territory } from "./types";
import generated from "./territories.generated.json";

/**
 * Real data for the 18 analysed municipalities, state/region aggregates and the Caatinga aggregate.
 * Generated by pipeline/territorios.py from MODIS 2001–2024 (rainfall removed), NISAR 2026, CHIRPS/ERA5-Land,
 * MapBiomas, Atlas Digital de Desastres and IBGE Census 2022. Fields listed in `estimativas` are labelled estimates.
 */
export const territories: Territory[] = generated.territories as Territory[];

export const territoriesMeta = generated.meta as {
  fontes: Record<string, string>;
  custo_restauracao_brl_ha: number;
  tco2e_por_ha: number;
  municipios: number;
  referencias: Record<string, string>;
};
